pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.deal(caller, amount);
        vm.prank(caller);
        uint256 balanceBefore = address(c).balance;
        vm.assume(amount > 0);
        c.deposit{value: amount}();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
